JOB="trackb_dense_grounding_v2_20261118"
SIGLIP_SHA256="97faeafa0576c1ba4c92bae739ca06ef5f5d0c2db92f86a6086653d82a262043"
V1_REV="1dcb8ade36980b0d4170583aea28840f09986ed1"

def atomic_json(path,obj):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True);tmp=path.with_suffix(path.suffix+".tmp")
    tmp.write_text(json.dumps(obj,indent=2,sort_keys=True,default=str)+"\n");os.replace(tmp,path)
def file_sha(path):
    h=hashlib.sha256()
    with open(path,"rb") as f:
        for b in iter(lambda:f.read(8<<20),b""):h.update(b)
    return h.hexdigest()
def write_report(out):
    status=json.loads((out/"RUN_STATUS.json").read_text())
    train=json.loads((out/"training_history.json").read_text()) if (out/"training_history.json").exists() else {}
    evroot=out/"evaluation"
    ev=json.loads((evroot/"evaluation_metrics.json").read_text()) if (evroot/"evaluation_metrics.json").exists() else {}
    thresholds=json.loads((evroot/"development_thresholds.json").read_text()) if (evroot/"development_thresholds.json").exists() else {}
    body=["# Track B Training V2 — Dense Language-Grounded Segmentation","",
          "Run status: **"+str(status.get("status","incomplete"))+"**. Generated by the persistent worker.","",
          "## Method","",
          "Frozen SigLIP text features supervise a trainable projection against the unchanged OpenVLA penultimate DINOv2 patch features. Training uses COCO 2014 instance-mask fractional 16x16 occupancy: weighted BCE, soft Dice, top-16 hard-negative penalty, and patch log-mean-exp symmetric InfoNCE. The only trainable module is Linear(1152,1024) -> Tanh -> Linear(1024,1024). Development/final val2014 manifests contain 1,000/3,000 images and exclude previous Phase 3 and 2,500-image segmentation IDs.","",
          "## Training",""]
    if train:
        hist=train.get("history",[]);best=train.get("best",{})
        body += ["- Completed epochs: "+str(len(hist))+" (maximum 40; early stopping after at least 12).",
                 "- Best development checkpoint epoch: "+str(best.get("epoch"))+".",
                 "- Best native-grid macro category mIoU: "+str(best.get("miou"))+".",
                 "- Development-selected threshold: "+str(best.get("threshold"))+".",
                 "- Latest total objective: "+str(hist[-1].get("total") if hist else "n/a")+".",""]
    body += ["## Development threshold calibration","",json.dumps(thresholds.get("selected_thresholds",{}),indent=2),"","## Final held-out evaluation",""]
    if ev:
        body += ["| Condition | 16x16 macro IoU | 224 macro IoU | Precision | Recall | FN rate | Background coverage proxy |","|---|---:|---:|---:|---:|---:|---:|"]
        for method,scales in ev.get("summary",{}).items():
            x=scales.get("grid16",{});y=scales.get("224",{})
            body.append(f"| {method} | {x.get('macro_category_miou')} | {y.get('macro_category_miou')} | {x.get('precision')} | {x.get('recall')} | {x.get('false_negative_foreground_rate')} | {x.get('candidate_background_coverage')} |")
        body.append("")
    else:body += ["Held-out evaluation pending or incomplete.",""]
    body += ["## Provenance and limitations","",
             "- V1 baseline reference commit: "+V1_REV+".",
             "- V1 epoch-50 comparison uses final-layer DINO features; V2 uses OpenVLA standard penultimate DINO features. This compares the systems as a whole, not the loss in isolation.",
             "- Native 16x16 labels are fractional occupancies; aligned 224 metrics compare lifted maps with exact transformed instance masks.",
             "- COCO category localization does not establish LIBERO task relevance, cache safety, or policy success.",
             "- Candidate background coverage is a segmentation proxy, not a KV-reuse safety metric or latency result.",
             "Full status: RUN_STATUS.json. Durable worker log: logs/pipeline.log.",""]
    libero=out/"libero_diagnostic"/"summary.json"
    body += ["## Offline LIBERO feasibility diagnostic","",(json.dumps(json.loads(libero.read_text()),indent=2) if libero.exists() else "Pending; no policy rollouts are part of this pipeline."),""]
    (out/"TRAINING_V2_REPORT.md").write_text("\n".join(body))

def main():
    p=argparse.ArgumentParser()
