    p.add_argument("--dataset-root",type=Path,default=Path("/opt/openvla/cache/datasets/talk2dino/coco2014"))
    p.add_argument("--model-root",type=Path,default=Path("/opt/openvla/cache/models/timm/ViT-SO400M-14-SigLIP-384"))
    p.add_argument("--cache-root",type=Path,default=Path("/opt/openvla/cache/datasets/talk2dino/coco2014/features_training_v2_dense_20261118"))
    p.add_argument("--train-text-cache-root",type=Path,default=Path("/opt/openvla/cache/datasets/talk2dino/coco2014/features_full_coco_20261117"))
    p.add_argument("--val-text-cache-root",type=Path,default=Path("/opt/openvla/cache/datasets/talk2dino/coco2014/features_full_validation_20261117"))
    p.add_argument("--v1-root",type=Path,default=Path("/opt/openvla/cache/worktrees/trackb-talk2dino-siglip/experiments/kv_cache/outputs/trackb_talk2dino_siglip/full_coco_training_20261117"))
    p.add_argument("--output",type=Path,default=Path("/opt/openvla/cache/worktrees/trackb-dense-grounding-v2/experiments/kv_cache/outputs/trackb_talk2dino_siglip/training_v2_dense_20261118"))
    p.add_argument("--resume",action="store_true")
    a=p.parse_args();out=a.output;logs=out/"logs";logs.mkdir(parents=True,exist_ok=True);log=logs/"pipeline.log";sp=out/"RUN_STATUS.json"
    import fcntl
    lock=(out/".worker.lock").open("w")
