        old=json.loads(sp.read_text()) if sp.exists() else {}
        atomic_json(sp,{**old,"status":"failed_recoverable","failed_stage":old.get("stage"),"error":type(e).__name__+": "+str(e),"traceback":tb,"exit_code":1,"updated_at":time.time(),"latest_checkpoint":str(a.cache_root/"checkpoints/latest.pt"),"resume_command":"python -m experiments.kv_cache.experiments.trackb_talk2dino_siglip.training_v2_dense.orchestrate --resume"})
        write_report(out);return 1
